import * as THREE from "three";

import type { BoneTree } from "./buildBoneTree";
import type { LoadedParticleEffect } from "./particles";
import { ParticleSystem } from "./particles";
import type { ParticleKeyframe } from "./types";

export interface EmoteParticlesOptions {
  effects: Map<string, LoadedParticleEffect>;
  rig: BoneTree;
  prop?: BoneTree | null;
  unitScale?: number;
}

export class EmoteParticles {
  readonly root: THREE.Group;

  private readonly system: ParticleSystem;
  private readonly rig: BoneTree;
  private readonly prop: BoneTree | null;
  private readonly unitScale: number;

  constructor(options: EmoteParticlesOptions) {
    this.system = new ParticleSystem();
    this.root = this.system.root;
    this.rig = options.rig;
    this.prop = options.prop ?? null;
    this.unitScale = options.unitScale ?? 1;
    for (const [id, loaded] of options.effects) this.system.register(id, loaded);
  }

  spawn(keyframe: ParticleKeyframe): void {
    if (!this.system.hasEffect(keyframe.effectId)) return;
    const anchor = this.anchorFor(keyframe.locator);
    if (keyframe.locator && !anchor) return;
    const target = anchor ?? this.rig.root;

    this.system.spawn(keyframe.effectId, {
      positionProvider: keyframe.bindToActor
        ? () => target.getWorldPosition(new THREE.Vector3())
        : target.getWorldPosition(new THREE.Vector3()),
      forceLifetime: "once",
      unitScale: this.unitScale,
    });
  }

  tick(elapsedSeconds: number, deltaSeconds: number): void {
    this.system.tick(elapsedSeconds, deltaSeconds);
  }

  dispose(): void {
    this.root.parent?.remove(this.root);
    this.system.dispose();
  }

  private anchorFor(name: string): THREE.Object3D | null {
    if (!name) return null;
    return (
      this.rig.bones.get(name) ??
      this.prop?.bones.get(name) ??
      this.rig.locators.get(name) ??
      this.prop?.locators.get(name) ??
      null
    );
  }
}
